#include "defines.hpp"
#include "deriche.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// img[i][j] with j the innermost (contiguous) dimension, as in C (img[W][H])
	DEFINE_PROTO_STRUCT(img_layout, j_vec ^ i_vec);
} tuning;

// initialization function
// imgIn, imgOut: i x j
void init_array(num_t &alpha, auto imgIn, auto imgOut) {
	using namespace noarr;
	(void)imgOut; // not used, kept for interface similarity

	alpha = SCALAR_VAL(0.25); // parameter of the filter

	// input should be between 0 and 1 (grayscale image pixel)
	traverser(imgIn).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		imgIn[state] = (num_t)(((313 * i + 991 * j) % 65536) / 65535.0f);
	});
}

// computation kernel
// imgIn, imgOut, y1, y2: i x j
//
// The implementation follows the standard 2D Deriche recursive filter:
//   - 1st vertical pass:  causal recursion along j for each i  -> y1
//   - 2nd vertical pass:  anti-causal recursion along j for each i -> y2
//   - vertical combine:   imgOut = c1 * (y1 + y2)
//   - 3rd horizontal pass: causal recursion along i for each j  -> y1
//   - 4th horizontal pass: anti-causal recursion along i for each j -> y2
//   - final combine:      imgOut = c2 * (y1 + y2)
//
// Compared to the baseline version, we:
//   * precompute and reuse exponentials when forming the coefficients,
//   * avoid recomputing i/j indices where they are loop-invariant,
//   * cache imgIn/imgOut loads in scalars inside the recurrences,
//   * keep all loop nests expressed via Noarr traversers.
[[gnu::flatten, gnu::noinline]]
void kernel_deriche(num_t alpha, auto imgIn, auto imgOut, auto y1, auto y2) {
	using namespace noarr;

	num_t k;
	num_t a1, a2, a3, a4, a5, a6, a7, a8;
	num_t b1, b2, c1, c2;

#pragma scop
	// ------------------------------------------------------------------
	// Coefficient setup
	// ------------------------------------------------------------------
	// Algebraically identical to the original C version, but we reuse
	// exp(-alpha), exp(-2*alpha), and exp(2*alpha) to avoid redundant
	// transcendental calls.
	const num_t exp_m_alpha  = EXP_FUN(-alpha);
	const num_t exp_m_2alpha = EXP_FUN(SCALAR_VAL(-2.0) * alpha);
	const num_t exp_p_2alpha = EXP_FUN(SCALAR_VAL(2.0) * alpha);

	k = (SCALAR_VAL(1.0) - exp_m_alpha) *
	    (SCALAR_VAL(1.0) - exp_m_alpha) /
	    (SCALAR_VAL(1.0) + SCALAR_VAL(2.0) * alpha * exp_m_alpha - exp_p_2alpha);

	a1 = a5 = k;
	a2 = a6 = k * exp_m_alpha * (alpha - SCALAR_VAL(1.0));
	a3 = a7 = k * exp_m_alpha * (alpha + SCALAR_VAL(1.0));
	a4 = a8 = -k * exp_m_2alpha;

	b1 = POW_FUN(SCALAR_VAL(2.0), -alpha);
	b2 = -exp_m_2alpha;
	c1 = c2 = SCALAR_VAL(1.0);

	// lengths used for reverse traversals
	const std::size_t w_len = imgIn | get_length<'i'>();
	const std::size_t h_len = imgIn | get_length<'j'>();

	// ------------------------------------------------------------------
	// 1st pass: causal filter along j, for each i (forward j)
	//
	// For each fixed i (row), this is a 1D IIR along the contiguous
	// dimension j:
	//   y1[i][j] = a1 * x[i][j]
	//            + a2 * x[i][j-1]
	//            + b1 * y1[i][j-1]
	//            + b2 * y1[i][j-2]
	// with x = imgIn and zero boundary conditions at j = -1, -2.
	// ------------------------------------------------------------------
	traverser(y1, imgIn).template for_dims<'i'>([&](auto inner) {
		num_t ym1 = SCALAR_VAL(0.0); // y1[i][j-1]
		num_t ym2 = SCALAR_VAL(0.0); // y1[i][j-2]
		num_t xm1 = SCALAR_VAL(0.0); // x[i][j-1]

		inner.template for_each<'j'>([&](auto state) {
			const num_t x = imgIn[state];
			const num_t y = a1 * x + a2 * xm1 + b1 * ym1 + b2 * ym2;

			y1[state] = y;

			xm1 = x;
			ym2 = ym1;
			ym1 = y;
		});
	});

	// ------------------------------------------------------------------
	// 2nd pass: anti-causal filter along j, for each i (reverse j)
	//
	// Original C code iterates j from H-1 down to 0 with recurrences:
	//   y2[i][j] = a3 * x[i][j+1]
	//            + a4 * x[i][j+2]
	//            + b1 * y2[i][j+1]
	//            + b2 * y2[i][j+2]
	//
	// We respect that dependence by mapping a forward "r" index to
	// j = H-1-r, so that updates still happen in the correct reverse
	// order along the physical j dimension.
	// ------------------------------------------------------------------
	traverser(y2, imgIn).template for_dims<'i'>([&](auto inner) {
		// i is fixed within this inner traverser; retrieve it once
		const std::size_t i_idx = get_index<'i'>(inner.state());

		num_t yp1 = SCALAR_VAL(0.0); // y2[i][j+1]
		num_t yp2 = SCALAR_VAL(0.0); // y2[i][j+2]
		num_t xp1 = SCALAR_VAL(0.0); // x[i][j+1]
		num_t xp2 = SCALAR_VAL(0.0); // x[i][j+2]

		inner.template for_each<'j'>([&](auto fwd_state) {
			const std::size_t r_j   = get_index<'j'>(fwd_state);
			const std::size_t j_idx = h_len - 1 - r_j;
			auto rev_state          = idx<'i', 'j'>(i_idx, j_idx);

			const num_t y = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;
			y2[rev_state] = y;

			const num_t x = imgIn[rev_state];
			xp2 = xp1;
			xp1 = x;
			yp2 = yp1;
			yp1 = y;
		});
	});

	// ------------------------------------------------------------------
	// Combine vertical passes:
	//   imgOut[i][j] = c1 * (y1[i][j] + y2[i][j]);
	//
	// This is purely pointwise and traversed in row-major order
	// (i outer, j inner) to stream over contiguous j.
	// ------------------------------------------------------------------
	traverser(imgOut, y1, y2).for_each([&](auto state) {
		imgOut[state] = c1 * (y1[state] + y2[state]);
	});

	// ------------------------------------------------------------------
	// 3rd pass: causal filter along i, for each j (forward i)
	//
	// For each fixed j (column), a 1D IIR along the i dimension:
	//   y1[i][j] = a5 * imgOut[i][j]
	//            + a6 * imgOut[i-1][j]
	//            + b1 * y1[i-1][j]
	//            + b2 * y1[i-2][j]
	// with zero boundary conditions at i = -1, -2.
	// ------------------------------------------------------------------
	traverser(y1, imgOut).template for_dims<'j'>([&](auto inner) {
		num_t tm1 = SCALAR_VAL(0.0); // imgOut[i-1][j]
		num_t ym1 = SCALAR_VAL(0.0); // y1[i-1][j]
		num_t ym2 = SCALAR_VAL(0.0); // y1[i-2][j]

		inner.template for_each<'i'>([&](auto state) {
			const num_t x = imgOut[state];
			const num_t y = a5 * x + a6 * tm1 + b1 * ym1 + b2 * ym2;

			y1[state] = y;

			tm1 = x;
			ym2 = ym1;
			ym1 = y;
		});
	});

	// ------------------------------------------------------------------
	// 4th pass: anti-causal filter along i, for each j (reverse i)
	//
	// Original C loops i from W-1 down to 0:
	//   y2[i][j] = a7 * imgOut[i+1][j]
	//            + a8 * imgOut[i+2][j]
	//            + b1 * y2[i+1][j]
	//            + b2 * y2[i+2][j]
	//
	// We again implement a logical reverse traversal along i by mapping
	// a forward r index to i = W-1-r for correctness and clarity.
	// ------------------------------------------------------------------
	traverser(y2, imgOut).template for_dims<'j'>([&](auto inner) {
		// j is fixed within this inner traverser; retrieve it once
		const std::size_t j_idx = get_index<'j'>(inner.state());

		num_t tp1 = SCALAR_VAL(0.0); // imgOut[i+1][j]
		num_t tp2 = SCALAR_VAL(0.0); // imgOut[i+2][j]
		num_t yp1 = SCALAR_VAL(0.0); // y2[i+1][j]
		num_t yp2 = SCALAR_VAL(0.0); // y2[i+2][j]

		inner.template for_each<'i'>([&](auto fwd_state) {
			const std::size_t r_i   = get_index<'i'>(fwd_state);
			const std::size_t i_idx = w_len - 1 - r_i;
			auto rev_state          = idx<'i', 'j'>(i_idx, j_idx);

			const num_t y = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;
			y2[rev_state] = y;

			const num_t x = imgOut[rev_state];
			tp2 = tp1;
			tp1 = x;
			yp2 = yp1;
			yp1 = y;
		});
	});

	// ------------------------------------------------------------------
	// Final combine:
	//   imgOut[i][j] = c2 * (y1[i][j] + y2[i][j]);
	// ------------------------------------------------------------------
	traverser(imgOut, y1, y2).for_each([&](auto state) {
		imgOut[state] = c2 * (y1[state] + y2[state]);
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t w = W;
	std::size_t h = H;

	// parameter
	num_t alpha;

	// lengths shared by all images
	auto set_lengths =
		noarr::set_length<'i'>(w) ^
		noarr::set_length<'j'>(h);

	// images: i x j
	auto imgIn  = noarr::bag(noarr::scalar<num_t>() ^ tuning.img_layout ^ set_lengths);
	auto imgOut = noarr::bag(noarr::scalar<num_t>() ^ tuning.img_layout ^ set_lengths);
	auto y1     = noarr::bag(noarr::scalar<num_t>() ^ tuning.img_layout ^ set_lengths);
	auto y2     = noarr::bag(noarr::scalar<num_t>() ^ tuning.img_layout ^ set_lengths);

	// initialize data
	init_array(alpha, imgIn.get_ref(), imgOut.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_deriche(alpha, imgIn.get_ref(), imgOut.get_ref(), y1.get_ref(), y2.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (acts as DCE prevention)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, imgOut.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
