// computation kernel
// imgIn, imgOut, y1, y2: i x j
//
// This implements the 2D Deriche filter as four 1D recursive passes
// (two vertical, two horizontal) plus two pointwise combinations.
// Recurrences are strictly along one spatial dimension; the orthogonal
// dimension is used for parallelism. All loop nests are expressed via
// Noarr traversers; OpenMP is used only to parallelize across
// independent scan lines.
[[gnu::flatten, gnu::noinline]]
void kernel_deriche(num_t alpha, auto imgIn, auto imgOut, auto y1, auto y2) {
	using namespace noarr;

	// Filter coefficients (loop-invariant scalars).
	num_t k;
	num_t a1, a2, a3, a4, a5, a6, a7, a8;
	num_t b1, b2, c1, c2;

#pragma scop
	// --------------------------------------------------------------------
	// Coefficient setup
	// --------------------------------------------------------------------
	// We factor out exponentials to avoid recomputing them.
	const num_t exp_neg_alpha  = EXP_FUN(-alpha);
	const num_t exp_pos_2alpha = EXP_FUN(SCALAR_VAL(2.0) * alpha);
	const num_t exp_neg_2alpha = EXP_FUN(SCALAR_VAL(-2.0) * alpha);

	k = (SCALAR_VAL(1.0) - exp_neg_alpha) *
	    (SCALAR_VAL(1.0) - exp_neg_alpha) /
	    (SCALAR_VAL(1.0) + SCALAR_VAL(2.0) * alpha * exp_neg_alpha -
	     exp_pos_2alpha);

	a1 = a5 = k;
	a2 = a6 = k * exp_neg_alpha * (alpha - SCALAR_VAL(1.0));
	a3 = a7 = k * exp_neg_alpha * (alpha + SCALAR_VAL(1.0));
	a4 = a8 = -k * exp_neg_2alpha;
	b1 = POW_FUN(SCALAR_VAL(2.0), -alpha);
	b2 = -exp_neg_2alpha;
	c1 = c2 = SCALAR_VAL(1.0);

	// Cached lengths (used for reverse traversals).
	const std::size_t w_len = imgIn | get_length<'i'>();
	const std::size_t h_len = imgIn | get_length<'j'>();

	// --------------------------------------------------------------------
	// 1st pass: causal filter along j, for each i (forward j)
	// --------------------------------------------------------------------
	// For each fixed i, this is a 2nd-order IIR recurrence along the
	// contiguous j dimension:
	//   y1[i][j] = a1 * x[i][j] + a2 * x[i][j-1]
	//              + b1 * y1[i][j-1] + b2 * y1[i][j-2]
	// with (xm1, ym1, ym2) initialized to 0 at j=-1,-2.
	{
		auto trav = traverser(y1, imgIn); // top-level dimension is 'i'

		// Parallelize across rows (independent scan lines) using the
		// traverser iterator. Each 'inner' traverser has 'i' fixed and
		// iterates sequentially over 'j'.
		#pragma omp parallel for schedule(static)
		for (auto inner : trav) {
			num_t ym1 = SCALAR_VAL(0.0);
			num_t ym2 = SCALAR_VAL(0.0);
			num_t xm1 = SCALAR_VAL(0.0);

			inner.template for_each<'j'>([&](auto state) {
				const num_t x = imgIn[state];
				const num_t y = a1 * x + a2 * xm1 + b1 * ym1 + b2 * ym2;

				y1[state] = y;

				xm1 = x;
				ym2 = ym1;
				ym1 = y;
			});
		}
	}

	// --------------------------------------------------------------------
	// 2nd pass: anti-causal filter along j, for each i (reverse j)
	// --------------------------------------------------------------------
	// Original C loops j from H-1 down to 0, with loop-carried state:
	//   y2[i][j] = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;
	//   xp2 = xp1; xp1 = imgIn[i][j];
	//   yp2 = yp1; yp1 = y2[i][j];
	//
	// Here we traverse j in 0..H-1 and map r -> j = H-1-r; this yields
	// the same sequence of (i,j) coordinates while keeping a standard
	// Noarr traversal on j.
	{
		auto trav = traverser(y2, imgIn); // top-level 'i'

		#pragma omp parallel for schedule(static)
		for (auto inner : trav) {
			num_t yp1 = SCALAR_VAL(0.0);
			num_t yp2 = SCALAR_VAL(0.0);
			num_t xp1 = SCALAR_VAL(0.0);
			num_t xp2 = SCALAR_VAL(0.0);

			inner.template for_each<'j'>([&](auto state) {
				auto [i_idx, r_j] = get_indices<'i', 'j'>(state);
				const std::size_t j_idx = h_len - 1 - r_j;
				auto rev_state = idx<'i', 'j'>(i_idx, j_idx);

				const num_t y = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;
				y2[rev_state] = y;

				xp2 = xp1;
				xp1 = imgIn[rev_state];
				yp2 = yp1;
				yp1 = y;
			});
		}
	}

	// --------------------------------------------------------------------
	// Vertical combination:
	//   imgOut[i][j] = c1 * (y1[i][j] + y2[i][j]);
	// --------------------------------------------------------------------
	// This is a purely pointwise operation; we again parallelize across
	// independent rows and iterate j sequentially within each row.
	{
		auto trav = traverser(imgOut, y1, y2);

		#pragma omp parallel for schedule(static)
		for (auto inner : trav) {
			inner.for_each([&](auto state) {
				imgOut[state] = c1 * (y1[state] + y2[state]);
			});
		}
	}

	// --------------------------------------------------------------------
	// 3rd pass: causal filter along i, for each j (forward i)
	// --------------------------------------------------------------------
	// For each fixed j, this is a 2nd-order IIR along i:
	//   y1[i][j] = a5 * imgOut[i][j] + a6 * imgOut[i-1][j]
	//              + b1 * y1[i-1][j] + b2 * y1[i-2][j]
	//
	// We hoist 'j' so that the traverser iterator iterates columns
	// (independent), and the inner for_each walks i sequentially.
	{
		auto trav = traverser(y1, imgOut).order(hoist<'j'>()); // top-level 'j'

		#pragma omp parallel for schedule(static)
		for (auto inner : trav) {
			num_t tm1 = SCALAR_VAL(0.0); // previous imgOut[i-1][j]
			num_t ym1 = SCALAR_VAL(0.0); // previous y1[i-1][j]
			num_t ym2 = SCALAR_VAL(0.0); // previous y1[i-2][j]

			inner.template for_each<'i'>([&](auto state) {
				const num_t x = imgOut[state];
				const num_t y = a5 * x + a6 * tm1 + b1 * ym1 + b2 * ym2;

				y1[state] = y;

				tm1 = x;
				ym2 = ym1;
				ym1 = y;
			});
		}
	}

	// --------------------------------------------------------------------
	// 4th pass: anti-causal filter along i, for each j (reverse i)
	// --------------------------------------------------------------------
	// Original C loops i from W-1 down to 0 with:
	//   y2[i][j] = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;
	//   tp2 = tp1; tp1 = imgOut[i][j];
	//   yp2 = yp1; yp1 = y2[i][j];
	//
	// As in the vertical anti-causal pass, we keep a forward traversal
	// along i and map r -> i = W-1-r.
	{
		auto trav = traverser(y2, imgOut).order(hoist<'j'>()); // top-level 'j'

		#pragma omp parallel for schedule(static)
		for (auto inner : trav) {
			num_t tp1 = SCALAR_VAL(0.0);
			num_t tp2 = SCALAR_VAL(0.0);
			num_t yp1 = SCALAR_VAL(0.0);
			num_t yp2 = SCALAR_VAL(0.0);

			inner.template for_each<'i'>([&](auto state) {
				auto [r_i, j_idx] = get_indices<'i', 'j'>(state);
				const std::size_t i_idx = w_len - 1 - r_i;
				auto rev_state = idx<'i', 'j'>(i_idx, j_idx);

				const num_t y = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;
				y2[rev_state] = y;

				tp2 = tp1;
				tp1 = imgOut[rev_state];
				yp2 = yp1;
				yp1 = y;
			});
		}
	}

	// --------------------------------------------------------------------
	// Final combination:
	//   imgOut[i][j] = c2 * (y1[i][j] + y2[i][j]);
	// --------------------------------------------------------------------
	// Again purely elementwise; parallelized across independent rows.
	{
		auto trav = traverser(imgOut, y1, y2);

		#pragma omp parallel for schedule(static)
		for (auto inner : trav) {
			inner.for_each([&](auto state) {
				imgOut[state] = c2 * (y1[state] + y2[state]);
			});
		}
	}
#pragma endscop
}

} // namespace

