#pragma scop
	// ------------------------------------------------------------------
	// Coefficient setup
	// ------------------------------------------------------------------
	// We factor out the transcendental calls so that EXP_FUN / POW_FUN are
	// evaluated only once per kernel invocation.
	const num_t em1    = EXP_FUN(-alpha);                         // e^{-alpha}
	const num_t em2    = EXP_FUN(SCALAR_VAL(-2.0) * alpha);       // e^{-2 alpha}
	const num_t e2a    = EXP_FUN(SCALAR_VAL(2.0) * alpha);        // e^{ 2 alpha}
	const num_t pow2ma = POW_FUN(SCALAR_VAL(2.0), -alpha);        // 2^{-alpha}

	const num_t k = (SCALAR_VAL(1.0) - em1) * (SCALAR_VAL(1.0) - em1) /
