	const num_t a5 = k;

	const num_t a2 = k * em1 * (alpha - SCALAR_VAL(1.0));
	const num_t a6 = a2;

	const num_t a3 = k * em1 * (alpha + SCALAR_VAL(1.0));
	const num_t a7 = a3;

	const num_t a4 = -k * em2;
	const num_t a8 = a4;

