			const auto [i_idx, r_j] = get_indices<'i', 'j'>(state);
			const std::size_t j_idx = h_len - 1 - r_j;
			const auto rev_state = idx<'i', 'j'>(i_idx, j_idx);

			// Anti-causal recurrence (y2) in reverse-j order
			const num_t y2_val = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;

			// Combine vertical passes on the fly:
			//   imgOut = c1 * (y1 + y2)
			imgOut[rev_state] = c1 * (y1[rev_state] + y2_val);

			const num_t x = imgIn[rev_state];

			xp2 = xp1;
			xp1 = x;
			yp2 = yp1;
			yp1 = y2_val;
		});
	});

	// ------------------------------------------------------------------
	// 3rd pass: causal filter along i, for each j (horizontal forward)
	//
	// For each fixed j, we run a 1D recurrence along i:
	//   y1[i][j] = a5*imgOut[i][j] + a6*imgOut[i-1][j]
	//              + b1*y1[i-1][j] + b2*y1[i-2][j]
	// with boundary conditions tm1 = ym1 = ym2 = 0 at i = -1, -2.
	// ------------------------------------------------------------------
	traverser(imgOut).template for_dims<'j'>([&](auto inner) {
		num_t tm1 = SCALAR_VAL(0.0);
		num_t ym1 = SCALAR_VAL(0.0);
		num_t ym2 = SCALAR_VAL(0.0);

		inner.template for_each<'i'>([&](auto state) {
			const num_t x = imgOut[state];
			const num_t y = a5 * x + a6 * tm1 + b1 * ym1 + b2 * ym2;

			y1[state] = y;

			tm1 = x;
			ym2 = ym1;
			ym1 = y;
		});
	});

	// ------------------------------------------------------------------
	// 4th pass: anti-causal filter along i, for each j (horizontal backward)
	//
	// Original C loops i from W-1 down to 0. We again use a forward index
	// r_i in [0, W) and map:
	//   r_i -> i = W-1-r_i
	//
	// We fuse this pass with the final combine:
	//   imgOut[i][j] = c2 * (y1[i][j] + y2[i][j])
	//
	// Important: the recurrence uses the *vertical* output imgOut as its
	// input. To preserve semantics we read the original imgOut value into
	// 'orig_x' before overwriting imgOut[rev_state] with the final result,
	// and we feed 'orig_x' into the recurrence state.
	// ------------------------------------------------------------------
	traverser(imgOut).template for_dims<'j'>([&](auto inner) {
		num_t tp1 = SCALAR_VAL(0.0);
		num_t tp2 = SCALAR_VAL(0.0);
		num_t yp1 = SCALAR_VAL(0.0);
		num_t yp2 = SCALAR_VAL(0.0);

		inner.template for_each<'i'>([&](auto state) {
			const auto [r_i, j_idx] = get_indices<'i', 'j'>(state);
			const std::size_t i_idx = w_len - 1 - r_i;
			const auto rev_state = idx<'i', 'j'>(i_idx, j_idx);

			// Input to the anti-causal recurrence: vertical imgOut value.
			const num_t orig_x = imgOut[rev_state];

			// Anti-causal recurrence (y2) in reverse-i order
			const num_t y2_val = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;

			// Final combine on the fly:
			//   imgOut = c2 * (y1 + y2)
			imgOut[rev_state] = c2 * (y1[rev_state] + y2_val);

			tp2 = tp1;
			tp1 = orig_x;
			yp2 = yp1;
			yp1 = y2_val;
		});
	});
#pragma endscop
}

} // namespace

